local bag = {"sword", "shield"}
table.clear(bag)
print(#bag) -- 0

local colors = {"red", "green", "blue"}
print(table.find(colors, "blue"))  -- 3
print(table.find(colors, "pink"))  -- nil

local line = {"Ava", "Ben"}
table.insert(line, "Cal")      -- {"Ava", "Ben", "Cal"}
table.insert(line, 1, "Zoe")   -- {"Zoe", "Ava", "Ben", "Cal"}
print(table.concat(line, ", "))

local a = {4, 5}
local b = {1, 2, 3}
table.move(a, 1, 2, 4, b) -- copy a[1] to a[2] into b starting at b[4]
print(table.concat(b, ",")) -- 1,2,3,4,5

-- Any script
local a = {}
local b = {}
print(rawequal(a, a)) --> true
print(rawequal(a, b)) --> false (two different tables)

-- Any script
local Dog = {}
Dog.__index = Dog

function Dog.new(name)
	return setmetatable({ name = name }, Dog)
end

function Dog:bark()
	print(self.name .. " says woof!")
end

Dog.new("Rex"):bark() --> Rex says woof!

-- Any script
local ok, result = xpcall(function()
	error("broken!")
end, function(err)
	return "Handled: " .. tostring(err)
end)
print(ok, result) --> false  Handled: ...broken!
